 66→  var STATUS_HEADINGS = {
 67→    decided: "We have made a decision",
 68→    under_review: "Your case is still under review",
 69→    passed_to_support: "Your report has been passed to our support team",
 70→    needs_info: "We need a little more information"
 71→  };
 72→
 73→  var state = {
 74→    category: null,
 75→    tripId: null,
 76→    trips: [],
 77→    runId: null
 78→  };
