 80→  // W30: request ownership. The trip list loads asynchronously, so only the newest
 81→  // request may render or land. Every load, category reset and trip Back bumps this
 82→  // epoch; a callback whose captured epoch no longer matches changes nothing.
 83→  var tripRequestEpoch = 0;
 84→
 85→  // W20: one serialized intake answer — choice, delimiter and explanation together —
 86→  // is at most this many Unicode code points. The form refuses locally before any
 87→  // request and leaves every control exactly as the party left it.
 88→  var MAX_INTAKE_ANSWER_CODE_POINTS = 2000;
 89→  var INTAKE_ANSWER_TOO_LONG = "Intake answers must be at most 2000 characters.";
