102→  var stepCategory = document.getElementById("step-category");
103→  var stepTrip = document.getElementById("step-trip");
104→  var stepDetails = document.getElementById("step-details");
105→  var outcomePanel = document.getElementById("outcome");
106→  var categoryOptions = document.getElementById("category-options");
107→  var tripOptions = document.getElementById("trip-options");
108→  var questionList = document.getElementById("question-list");
109→  var questionBoxes = document.getElementById("question-boxes");
110→  var outcomeTitle = document.getElementById("outcome-title");
111→  var outcomeReference = document.getElementById("outcome-reference");
112→  var outcomeMessage = document.getElementById("outcome-message");
113→  var outcomeQuestions = document.getElementById("outcome-questions");
114→  var outcomeStatus = document.getElementById("outcome-status");
