123→  // W35: the pending state of "Send my dispute". Fixed text, built here.
124→  var SUBMIT_LABEL = "Send my dispute";
125→  var SENDING_LABEL = "Sending…";
126→  var SENDING_STATUS = "Sending your dispute. This can take a little while, so please keep this page open.";
127→  var sending = false;
