129→  function element(tag, className, text) {
130→    var node = document.createElement(tag);
131→    if (className) {
132→      node.className = className;
133→    }
134→    if (text !== undefined && text !== null) {
135→      node.textContent = String(text);
136→    }
137→    return node;
138→  }
139→
140→  function showError(id, message) {
141→    var node = document.getElementById(id);
142→    node.textContent = message;
143→    node.hidden = false;
144→  }
145→
146→  function clearError(id) {
147→    var node = document.getElementById(id);
148→    node.textContent = "";
149→    node.hidden = true;
150→  }
151→
152→  function show(node) {
153→    node.hidden = false;
154→  }
155→
156→  function hide(node) {
157→    node.hidden = true;
158→  }
159→
160→  // Unicode code points, not UTF-16 code units: an astral character (an emoji) is
161→  // one character to the server and must be one here too.
162→  function codePointCount(text) {
163→    var count = 0;
164→    for (var i = 0; i < text.length; i += 1) {
165→      var code = text.charCodeAt(i);
166→      if (code >= 0xD800 && code <= 0xDBFF && i + 1 < text.length) {
167→        var next = text.charCodeAt(i + 1);
168→        if (next >= 0xDC00 && next <= 0xDFFF) {
169→          i += 1;
170→        }
171→      }
172→      count += 1;
173→    }
174→    return count;
175→  }
176→
177→  function request(method, path, body) {
178→    var options = { method: method };
179→    if (body !== undefined) {
180→      options.headers = { "Content-Type": "application/json" };
181→      options.body = JSON.stringify(body);
182→    }
183→    return fetch(path, options).then(function (response) {
184→      return response.json().then(function (payload) {
185→        if (!response.ok) {
186→          var reason = payload && payload.error ? payload.error : "Something went wrong. Please try again.";
187→          throw new Error(reason);
188→        }
189→        return payload;
190→      });
191→    });
192→  }
193→
194→  // ------------------------------------------------------------- page role
195→
196→  // The shell's own marker selects the questionnaire and the category copy. A
197→  // missing marker is the original rider shell; any other explicit value refuses
198→  // the whole page. This is demo copy selection, not authentication: the role is
199→  // never read from the URL, the document body or the fixed driver account.
200→  var formSteps = document.getElementById("form-steps");
201→  var role = formSteps.getAttribute("data-filed-by");
202→  if (role === null) {
203→    role = "rider";
204→  }
205→  var QUESTIONNAIRES = QUESTIONNAIRES_BY_ROLE[role];
206→  var CATEGORIES = CATEGORIES_BY_ROLE[role];
207→  if (role !== "rider" && role !== "driver") {
208→    showError("category-error",
209→      "This filing page could not be loaded. Please return to the help page and try again.");
210→    return;
211→  }
212→
213→  // ------------------------------------------------------------- step one
214→
215→  CATEGORIES.forEach(function (category) {
216→    var card = element("button", "option-card", category.label);
217→    card.type = "button";
218→    card.addEventListener("click", function () {
219→      state.category = category.id;
220→      Array.prototype.forEach.call(categoryOptions.children, function (child) {
221→        child.classList.remove("selected");
222→      });
223→      card.classList.add("selected");
224→      document.getElementById("category-next").disabled = false;
225→      // Changing the category resets everything downstream (R3 page side): the trip
226→      // list belongs to the category, so a trip picked for one category must never
227→      // survive a switch to another, and neither must any answer (W20) — the shared
228→      // safety question included. The epoch bump abandons any in-flight load.
229→      tripRequestEpoch += 1;
230→      state.tripId = null;
231→      rememberedTripId = null;
232→      questionsKey = null;
233→      while (questionList.firstChild) {
234→        questionList.removeChild(questionList.firstChild);
235→      }
236→      while (tripOptions.firstChild) {
237→        tripOptions.removeChild(tripOptions.firstChild);
238→      }
239→      document.getElementById("trip-next").disabled = true;
240→      clearError("trip-error");
241→      clearError("details-error");
242→      hide(stepTrip);
243→      hide(stepDetails);
244→    });
245→    categoryOptions.appendChild(card);
246→  });
247→
248→  document.getElementById("category-next").addEventListener("click", function () {
249→    clearError("category-error");
250→    hide(stepCategory);
251→    show(stepTrip);
252→    hide(stepDetails);
253→    loadTrips();
254→  });
255→
256→  // ------------------------------------------------------------- step two
257→
258→  // W30: bring the whole trip card on screen once the list has rendered. The card
259→  // is at most one screen tall, so aligning its top shows the Continue/Back bar
260→  // too. A response that arrives after the party pressed Back must not move the
261→  // page, so a hidden trip step is left alone.
262→  function landTripCard() {
263→    if (stepTrip.hidden) {
264→      return;
265→    }
266→    stepTrip.scrollIntoView({ block: "start" });
267→  }
268→
269→  // The visible lines of a trip: route, date and kind, then the trip id and the
270→  // charge. W35: the step 2 card and the step 3 summary both render through here,
271→  // so the summary repeats exactly what the party picked.
272→  function tripLines(trip) {
273→    var meta = [trip.date, trip.kind_label].filter(Boolean).join(" · ");
274→    var charge = "";
275→    if (trip.fare_sgd !== null && trip.fare_sgd !== undefined) {
276→      charge = " · SGD " + Number(trip.fare_sgd).toFixed(2)
277→        + (trip.charge_label ? " " + trip.charge_label : "");
278→    }
279→    var detail = element("span", "trip-meta", "");
280→    detail.textContent = "Trip " + trip.trip_id + charge;
281→    return [
282→      element("strong", null, trip.label),
283→      element("span", "trip-meta", meta),
284→      detail
285→    ];
286→  }
287→
288→  function loadTrips() {
289→    var epoch = ++tripRequestEpoch;
290→    // W20: the trip picked before this reload is remembered so the rendered list can
291→    // restore it — Back from the details step must not lose the party's selection,
292→    // even when an earlier attempt failed or its list omitted the trip.
293→    var wanted = rememberedTripId;
294→    clearError("trip-error");
295→    var boxes = tripOptions;
296→    while (boxes.firstChild) {
297→      boxes.removeChild(boxes.firstChild);
298→    }
299→    state.tripId = null;
300→    document.getElementById("trip-next").disabled = true;
301→    boxes.appendChild(element("p", "loading", "Loading trips…"));
302→    request("GET", "/api/trips?category=" + encodeURIComponent(state.category))
303→      .then(function (payload) {
304→        if (epoch !== tripRequestEpoch) {
305→          return;
306→        }
307→        while (boxes.firstChild) {
308→          boxes.removeChild(boxes.firstChild);
309→        }
310→        state.trips = Array.isArray(payload.trips) ? payload.trips : [];
311→        if (state.trips.length === 0) {
312→          boxes.appendChild(element("p", "hint", "No trips are available in the sample dataset."));
313→          landTripCard();
314→          return;
315→        }
316→        state.trips.forEach(function (trip) {
317→          var card = element("button", "option-card trip-card");
318→          card.type = "button";
319→          tripLines(trip).forEach(function (line) { card.appendChild(line); });
320→          card.addEventListener("click", function () {
321→            // W20: a different trip invalidates the answers on the details step; the
322→            // same trip (a re-click after Back) keeps them.
323→            if (questionsKey && questionsKey.tripId !== trip.trip_id) {
324→              questionsKey = null;
325→              while (questionList.firstChild) {
326→                questionList.removeChild(questionList.firstChild);
327→              }
328→            }
329→            state.tripId = trip.trip_id;
330→            rememberedTripId = trip.trip_id;
331→            Array.prototype.forEach.call(boxes.children, function (child) {
332→              child.classList.remove("selected");
333→            });
334→            card.classList.add("selected");
335→            document.getElementById("trip-next").disabled = false;
336→          });
337→          // W20: restore the selection the party already made when this reload's list
338→          // still carries that trip. A list without it leaves the step unselected.
339→          if (wanted !== null && trip.trip_id === wanted) {
340→            state.tripId = wanted;
341→            card.classList.add("selected");
342→            document.getElementById("trip-next").disabled = false;
343→          }
344→          boxes.appendChild(card);
345→        });
346→        landTripCard();
347→      })
348→      .catch(function (error) {
349→        if (epoch !== tripRequestEpoch) {
350→          return;
351→        }
352→        while (boxes.firstChild) {
353→          boxes.removeChild(boxes.firstChild);
354→        }
355→        showError("trip-error", error.message);
356→        landTripCard();
357→      });
358→  }
359→
360→  document.getElementById("trip-back").addEventListener("click", function () {
361→    // Back invalidates an outstanding load immediately: no new request has to
362→    // start for a late response to be stale.
363→    tripRequestEpoch += 1;
364→    show(stepCategory);
365→    hide(stepTrip);
366→    stepCategory.scrollIntoView({ block: "start" });
367→  });
368→
369→  document.getElementById("trip-next").addEventListener("click", function () {
370→    clearError("trip-error");
371→    hide(stepTrip);
372→    // W20: rebuild the questions only when the category or the trip changed; the
373→    // unchanged pair keeps the draft the party already typed.
374→    if (!questionsKey || questionsKey.category !== state.category
375→        || questionsKey.tripId !== state.tripId) {
376→      buildQuestions();
377→      questionsKey = { category: state.category, tripId: state.tripId };
378→    }
379→    renderSummary();
380→    show(stepDetails);
381→    window.scrollTo(0, 0);
382→  });
383→
384→  // --------------------------------------------------------- step three
385→
386→  // W35: a read-only summary of what is being filed, rebuilt every time the party
387→  // continues to this step, so a changed category or trip always shows.
388→  function renderSummary() {
389→    var category = CATEGORIES.filter(function (c) { return c.id === state.category; })[0];
390→    summaryCategory.textContent = category ? category.label : "";
391→    while (summaryTrip.firstChild) {
392→      summaryTrip.removeChild(summaryTrip.firstChild);
393→    }
394→    var trip = state.trips.filter(function (t) { return t.trip_id === state.tripId; })[0];
395→    if (trip) {
396→      tripLines(trip).forEach(function (line) { summaryTrip.appendChild(line); });
397→    }
398→  }
399→
400→  function setSending(on) {
401→    sending = on;
402→    detailsSubmit.disabled = on;
403→    detailsBack.disabled = on;
404→    detailsSubmit.textContent = on ? SENDING_LABEL : SUBMIT_LABEL;
405→    detailsSpinner.hidden = !on;
406→    detailsStatus.textContent = on ? SENDING_STATUS : "";
407→  }
