409→  function buildChoiceQuestion(question) {
410→    var field = element("div", "field");
411→    var label = element("label", null, question.label);
412→    // The choices container is a div, so a <label for> cannot point at it. The
413→    // question text reaches assistive tech via role="group" + aria-labelledby.
414→    label.id = "label-" + question.key;
415→    var choices = element("div", "choice-options");
416→    choices.id = "answer-" + question.key;
417→    choices.role = "group";
418→    choices.setAttribute("aria-labelledby", "label-" + question.key);
419→    var elaborate = element("textarea", "answer-input elaborate");
420→    elaborate.rows = 2;
421→    elaborate.setAttribute("data-elaborate-for", question.key);
422→    elaborate.placeholder = "Tell us more (optional)";
423→    elaborate.setAttribute("aria-label", "Tell us more: " + question.label);
424→    elaborate.hidden = true;
425→
426→    ["Yes", "No"].forEach(function (choice) {
427→      var button = element("button", "choice-button", choice);
428→      button.type = "button";
429→      button.setAttribute("data-choice", choice);
430→      button.setAttribute("aria-pressed", "false");
431→      button.dataset.questionKey = question.key;
432→      button.addEventListener("click", function () {
433→        if (!button.classList.contains("selected")) {
434→          elaborate.value = "";
435→        }
436→        Array.prototype.forEach.call(choices.children, function (sibling) {
437→          sibling.classList.remove("selected");
438→          sibling.setAttribute("aria-pressed", "false");
439→        });
440→        button.classList.add("selected");
441→        button.setAttribute("aria-pressed", "true");
442→        show(elaborate);
443→      });
444→      choices.appendChild(button);
445→    });
446→
447→    field.appendChild(label);
448→    field.appendChild(choices);
449→    field.appendChild(elaborate);
450→    return field;
451→  }
452→
453→  // W43 M1: the absence field is built with the other questions but not inside the
454→  // question list: the pinned list keeps exactly its three rows. Its host is the
455→  // container the list sits in, so it renders directly after the list; a DOM without
456→  // parent links falls back to the details step, which holds the field just the same.
457→  var absenceField = null;
458→  var absenceHost = null;
459→
460→  function placeAbsenceQuestion() {
461→    if (absenceField && absenceHost) {
462→      absenceHost.removeChild(absenceField);
463→    }
464→    absenceField = null;
465→    absenceHost = null;
466→    if (role !== "rider" || state.category !== "no_show_charge") {
467→      return;
468→    }
469→    absenceField = buildChoiceQuestion(ABSENCE_QUESTION);
470→    var host = questionList.parentNode;
471→    absenceHost = host && typeof host.appendChild === "function" ? host : stepDetails;
472→    absenceHost.appendChild(absenceField);
473→  }
474→
475→  function buildQuestions() {
476→    while (questionList.firstChild) {
477→      questionList.removeChild(questionList.firstChild);
478→    }
479→    var questions = QUESTIONNAIRES[state.category] || [];
480→    questions.forEach(function (question) {
481→      if (question.kind === "yes_no") {
482→        questionList.appendChild(buildChoiceQuestion(question));
483→      } else if (question.kind === "open") {
484→        var field = element("div", "field");
485→        var label = element("label", null, question.label);
486→        label.htmlFor = "answer-" + question.key;
487→        var input = element("textarea", "answer-input");
488→        input.id = "answer-" + question.key;
489→        input.rows = 2;
490→        input.dataset.questionKey = question.key;
491→        field.appendChild(label);
492→        field.appendChild(input);
493→        questionList.appendChild(field);
494→      }
495→    });
496→    placeAbsenceQuestion();
497→  }
498→
499→  document.getElementById("details-back").addEventListener("click", function () {
500→    hide(stepDetails);
501→    show(stepTrip);
502→    loadTrips();
503→  });
504→
505→  document.getElementById("details-form").addEventListener("submit", function (event) {
506→    event.preventDefault();
507→    if (sending) {
508→      return;
509→    }
510→    clearError("details-error");
511→    var description = document.getElementById("description").value;
512→    if (!description.trim()) {
513→      showError("details-error", "Please tell us what happened before sending.");
514→      return;
515→    }
516→    var amountText = document.getElementById("claim-amount").value.trim();
517→    var amount = null;
518→    if (amountText !== "") {
519→      amount = Number(amountText);
520→      if (!isFinite(amount) || amount < 0 || amount > 500) {
521→        showError("details-error", "The amount must be between 0 and 500 SGD.");
522→        return;
523→      }
524→    }
525→    var answers = {};
526→    (QUESTIONNAIRES[state.category] || []).forEach(function (question) {
527→      if (question.kind === "yes_no") {
528→        var selected = questionList.querySelector(
529→          '.choice-button.selected[data-question-key="' + question.key + '"]'
530→        );
531→        var elaborate = questionList.querySelector(
532→          'textarea[data-elaborate-for="' + question.key + '"]'
533→        );
534→        var choice = selected ? selected.dataset.choice : "";
535→        var elaboration = elaborate ? elaborate.value.trim() : "";
536→        answers[question.key] = choice
537→          ? (elaboration ? choice + " - " + elaboration : choice)
538→          : "";
539→      } else if (question.kind === "open") {
540→        var input = questionList.querySelector(
541→          'textarea[data-question-key="' + question.key + '"]'
542→        );
543→        answers[question.key] = input ? input.value : "";
544→      }
545→    });
546→
547→    // W43 M1: the absence answer is sent only when the party chose one. No choice,
548→    // no key: the record then carries no claim, exactly as it does today.
549→    if (absenceField) {
550→      var absenceChoice = absenceField.querySelector(".choice-button.selected[data-choice]");
551→      if (absenceChoice) {
552→        var absenceBox = absenceField.querySelector(
553→          'textarea[data-elaborate-for="' + ABSENCE_KEY + '"]'
554→        );
555→        var absenceText = absenceBox ? absenceBox.value.trim() : "";
556→        answers[ABSENCE_KEY] = absenceText
557→          ? absenceChoice.dataset.choice + " - " + absenceText
558→          : absenceChoice.dataset.choice;
559→      }
560→    }
561→
562→    // W20: the cap counts the complete serialized answer — choice, delimiter and
563→    // trimmed explanation together — in Unicode code points. Nothing is truncated
